home.css:
/* Orbit 2 — independent dossier + gallery. Only public SDK roots/regions. */
:scope { color:#f2f1eb; }
.main-content-wrapper {
 padding:clamp(112px, 14vh, 250px) 0 clamp(20px, 3vh, 64px);
 column-gap:clamp(24px, 3vw, 100px); row-gap:clamp(12px, 2vh, 38px);
}
.home-feature-stage {
 width:auto; height:100%; min-height:0; margin:0 0 0 clamp(30px, 4vw, 160px);
 align-self:stretch; align-content:stretch; transform:none;
 gap:clamp(18px, 3vh, 65px);
}
.home-feature-copy {
 width:100%; max-width:100%; padding:0; align-self:center;
 gap:clamp(8px, 1.3vh, 24px); align-content:center;
}
.home-feature-eyebrow { display:none; }
.home-feature-copy #gameLogo { margin:0 0 1vh; max-width:95%; max-height:clamp(64px, 10vh, 200px); }
.home-feature-title { max-width:25ch; }
.home-feature-meta span { padding:0; }
.home-feature-playtime {
 display:flex; flex-direction:column; align-items:flex-start;
 gap:4px; margin:clamp(6px, 1vh, 20px) 0; border:0; padding:0;
}
.home-feature-playtime[hidden] { display:none; }
.home-feature-playtime-label { color:#a5b2ae; font-size:clamp(12px, .8vw, 25px); letter-spacing:.06em; }
.home-feature-playtime strong { font-weight:400; }
.home-feature-primary { margin:0; }
.home-feature-art-shell {
 width:100%; height:auto; aspect-ratio:16 / 9; max-height:28vh;
 justify-self:stretch; align-self:end; transform:none;
}
.home-library-toolbar {
 width:100%; margin:0; min-height:40px; padding:0 clamp(24px, 2vw, 80px);
 align-self:end;
}
.home-library-rail { height:100%; display:flex; align-items:center; }
.home-library-rail .game-grid { padding-top:30px; padding-bottom:30px; }
.home-library-rail .card { border-radius:8px; }
.home-library-rail .card:focus, .home-library-rail .card.nav-focused-el { transform:translateY(-4px); }
.home-library-rail .card .title { font-size:clamp(13px, .95vw, 30px); font-weight:500; }
.main-content-wrapper .home-tab { border-radius:3px; color:#a5b2ae; font-size:clamp(14px, 1.05vw, 32px); }
.main-content-wrapper .home-tab.active { color:#f2f1eb; }
.main-content-wrapper .home-tab:focus, .main-content-wrapper .home-tab.nav-focused-el {
 background:#d9eee510; border-color:#d7eee1;
}
.home-controls-bar { width:calc(100% - 8vw); margin:0 auto; padding-top:2vh; border-top:1px solid #d6eee21a; }
.home-trailer-fullscreen-hint { bottom:0; right:0; font-size:clamp(12px, .8vw, 25px); }
@media (max-aspect-ratio: 4 / 3) {
 .main-content-wrapper { column-gap:20px; grid-template-columns:minmax(0, 40fr) minmax(0, 60fr); }
 .home-feature-stage { margin-left:28px; }
 .home-feature-copy #gameLogo { max-width:90%; }
}
@media (max-height: 800px) {
 .main-content-wrapper { padding-top:110px; padding-bottom:16px; row-gap:8px; }
 .home-feature-copy { gap:7px; }
 .home-feature-copy #gameLogo { max-height:58px; margin-bottom:2px; }
 .home-feature-art-shell { max-height:23vh; }
 .home-feature-stage { gap:12px; }
 .home-controls-bar { display:flex; padding-top:10px; }
}
@media (prefers-reduced-motion: reduce) {
 .card, .home-feature-copy { transition:none; }
}

/* Native cinema is entered only by the user. Contextual CSS stays inside Home. */
:scope:where(body.home-trailer-cinema *) .home-feature-copy {
 width:clamp(280px, 23vw, 600px); max-width:45vw; padding:18px;
 gap:10px; background:#101a1cdd; border-color:#d6eee226; border-radius:8px;
}
:scope:where(body.home-trailer-cinema *) .home-feature-copy #gameLogo {
 max-width:85%; max-height:10vh; margin:0;
}
:scope:where(body.home-trailer-cinema *) .home-feature-playtime { align-items:center; }

.home-controls-bar .gp-hint-label, .home-controls-bar .gp-hint-key { font-size:clamp(12px, .8vw, 25px); }

button, input, select, textarea { font-family:inherit; }

nav-menu.css:
/* Main menu: architectural frame, quiet categories, generous content canvas. */
:scope { background:#0c1215; color:#f2f1eb; font-family:'Segoe UI', system-ui, sans-serif; }
#navMenuBg { opacity:.06; }
.nav-layout { padding:clamp(28px, 4vw, 140px); gap:clamp(22px, 3vh, 60px); }
.nav-topbar { padding-top:0; border-bottom:1px solid #d6eee226; padding-bottom:clamp(14px, 2vh, 40px); }
.nav-cat-list { gap:clamp(12px, 1.5vw, 48px); }
.nav-cat-item { background:transparent; border-radius:3px; color:#a5b2ae; }
.nav-cat-item.active { color:#f2f1eb; border-color:transparent; box-shadow:inset 0 -2px 0 #b7dccc; }
.nav-cat-item.nav-focused { background:#e7eee7; color:#14211d; outline:2px solid #e7eee7; outline-offset:3px; }
.nav-content { border:1px solid #d6eee21a; border-radius:10px; background:#141d20; padding:clamp(20px, 2.5vw, 80px); }
.nav-content-title { color:#f2f1eb; font-weight:400; letter-spacing:-.03em; }
.nav-content-subtitle { color:#a5b2ae; }
.nav-settings-home-item { border-radius:5px; background:#1b2629; border:1px solid #d6eee21f; box-shadow:none; }
.nav-settings-home-item.nav-focused-el { background:#243731; border-color:#c6e9d8; box-shadow:inset 3px 0 0 #c6e9d8; }
.nav-settings-home-icon { background:transparent; color:#c6e9d8; }

/* Library: permanent, labelled tools beside a fluid catalogue wall.
   Keep the vertical tools at the left: core navigation traverses this boundary. */
:scope { --orbit-library-tools:clamp(150px, 13vw, 420px); }
.nav-library-pane { padding-left:calc(var(--orbit-library-tools) + 28px) !important; }
.nav-library-actions { left:clamp(24px, 4vw, 140px); top:clamp(180px, 24vh, 500px); width:var(--orbit-library-tools); gap:12px; }
.nav-library-action {
 width:100%; height:clamp(54px, 5vh, 108px); display:flex; align-items:center; justify-content:flex-start;
 gap:clamp(10px, 1vw, 32px); padding:12px; border:1px solid #d6eee226; border-left:0; border-radius:0 5px 5px 0;
 background:#1d2a2d; color:#c9d8d0; box-shadow:none;
}
.nav-library-action svg { width:clamp(22px, 1.7vw, 50px); height:clamp(22px, 1.7vw, 50px); flex-shrink:0; }
.nav-library-action > span, .nav-library-action.nav-focused-el > span {
 position:static; padding:0; opacity:1; transform:none; background:none; color:inherit;
 font-size:clamp(13px, 1vw, 30px); font-weight:500;
}
.nav-library-action.nav-focused-el { transform:none; background:#e7eee7; color:#14211d; border-color:#e7eee7; box-shadow:none; }
.nav-library-action.has-value::after { background:#b7dccc; }
.nav-big-grid { grid-template-columns:repeat(auto-fill,minmax(clamp(145px, 11.5vw, 360px),1fr)); gap:clamp(18px, 2vw, 60px); align-content:start; }
.nav-vertical-card { border-radius:6px; background:#223034; border:2px solid #d6eee21f; }
.nav-vertical-card.nav-focused { transform:translateY(-3px); border-color:#d7eee1; box-shadow:0 10px 28px #00000044; }
.nav-card-gradient { opacity:1; height:32%; background:linear-gradient(0deg,#081015f5,transparent); }
.nav-vertical-card-title { opacity:1; transform:none; text-align:left; font-size:clamp(13px, .9vw, 28px); padding:12px; }
.nav-library-search-sheet { background:#1c2b2d; border:1px solid #b7dccc; border-radius:6px; box-shadow:0 18px 56px #00000055; }
.nav-library-expanded-search input { color:#f2f1eb; font-weight:400; }
.nav-library-search-cancel { color:#c6e9d8; }
.nav-library-filter-panel { background:#172628; border:1px solid #b7dccc66; border-radius:8px; box-shadow:0 18px 56px #00000066; }
.nav-library-filter-option { border-radius:4px; color:#f2f1eb; }
.nav-library-filter-option.nav-focused-el { background:#293f36; border-color:#c6e9d8; box-shadow:none; }
.nav-library-filter-option.selected .nav-library-switch { background:#b7dccc; }
.nav-library-filter-option.selected .nav-library-switch i { background:#14211d; }
.nav-library-filter-footer button { border-radius:4px; }
.nav-library-filter-footer button.nav-focused-el { background:#e7eee7; color:#14211d; box-shadow:none; }
/* Profile and system settings keep their native controls inside the same frame. */
.nav-profile-cover, .nav-profile-recent-card { border-radius:6px; border-color:#d6eee226; box-shadow:none; }
.nav-profile-avatar-large { border-radius:10px; border-color:#b7dccc; }
.nav-settings-section-title { color:#b7dccc; letter-spacing:.06em; }
@media (max-height:800px) {
 .nav-layout { padding:22px; gap:14px; }
 .nav-topbar { padding-top:0; padding-bottom:12px; }
 .nav-content { padding:18px; }
 .nav-library-actions { left:30px; top:180px; }
 .nav-library-filter-panel { top:140px; max-height:calc(100vh - 180px); }
}

/* The header aligns with the cards, leaving a separate lane for the tools. */
.nav-content:has(.dual-pane-active) .nav-content-header { margin-left:calc(var(--orbit-library-tools) + 28px); }

/* Explicit readable floors also apply when the core uses a compact rem scale. */
.nav-cat-label { font-size:clamp(16px, 1vw, 36px); }
.nav-cat-item { padding:10px 16px; }
.nav-content-title { font-size:clamp(28px, 2vw, 64px); }
.nav-content-subtitle { font-size:clamp(14px, .95vw, 30px); }
.nav-library-action > span { font-size:clamp(15px, 1vw, 30px); }

button, input, select, textarea { font-family:inherit; }

side-panels.css:
/* Docked command panel + spacious two-column editors. Geometry of input is retained. */
:scope { color:#f2f1eb; background:#0c1215; font-family:'Segoe UI', system-ui, sans-serif; }
:scope.is-menu-only { background:#070d1199; }
.dq-content { color:#f2f1eb; background:#0c1215; }
.dq-heading, .dq-card h3 { color:#f2f1eb; }
.dq-kicker, .dq-sub, .dq-card p { color:#b5c4bd; }
.dq-card, .dq-action, .dq-release-notes, .dq-storage-category, .dq-program-row,
.dq-drive-tab, .dq-storage-node-group, .dq-program-action, .dq-storage-back {
 background:#172428; color:#f2f1eb; border-color:#d6eee226;
}
.dq-release-head { background:#172428; color:#b5c4bd; }
.dq-tab.active { color:#c6e9d8; border-bottom-color:#c6e9d8; }
.dq-card:focus, .dq-card.nav-focused-el, .dq-action:focus, .dq-action.nav-focused-el,
.dq-drive-tab:focus, .dq-drive-tab.nav-focused-el, .dq-program-action:focus,
.dq-storage-node-group:focus, .dq-storage-back:focus {
 background:#263c33; color:#f2f1eb; border-color:#c6e9d8; box-shadow:0 0 0 2px #c6e9d8;
}
.dq-action.primary { background:#e7eee7; color:#14211d; }
.dq-action.danger, .dq-program-action.danger { color:#ffc4c4; border-color:#ff969644; }
.dq-progress-fill, .dq-storage-drive-track i { background:#b7dccc; }
/* Embedded sound/network screens belong to the same scoped quick panel. */
.sound-panel, .sound-drawer, .sound-volume-card,
.wifi-detail-hero, .wifi-network-card, .wifi-toggle-row, .wifi-button, .wifi-back,
.bt-detail-hero, .bt-device-card, .bt-toggle-row, .bt-button, .bt-back, .bt-pairing-panel {
 background:#172428; color:#f2f1eb; border-color:#d6eee226;
}
.sound-focus:focus, .sound-focus.nav-focused-el,
.wifi-focus:focus, .wifi-focus.nav-focused-el,
.bluetooth-focus:focus, .bluetooth-focus.nav-focused-el {
 background:#263c33; border-color:#c6e9d8; box-shadow:0 0 0 2px #c6e9d8;
}
.sound-slider-rail i, .sound-slider-shell.active:focus-within .sound-slider-rail i,
.sound-volume-card.editing .sound-slider-rail i,
.wifi-toggle.on, .bt-toggle.on { background:#b7dccc; box-shadow:none; }
.wifi-eyebrow, .wifi-detail-hero p.connected, .wifi-network-state.connected,
.wifi-network-card.connected .wifi-network-copy span,
.bt-eyebrow, .bt-device-state.connected, .bt-detail-hero p.connected,
.bt-device-card.connected .bt-device-copy span, .bt-device-card.pairing .bt-device-copy span { color:#b7dccc; }
.wifi-network-card.connected, .bt-device-card.connected, .bt-device-card.pairing { border-color:#b7dccc66; background:#20372e; }
.wifi-button.primary, .bt-button.primary,
.bt-button.primary.bluetooth-focus:focus, .bt-button.primary.bluetooth-focus.nav-focused-el { background:#e7eee7; color:#14211d; }
.wifi-spinner, .bt-spinner, .bt-card-spinner { border-color:#b7dccc40; border-top-color:#b7dccc; }
.dq-sidebar {
 width:clamp(340px, 28vw, 900px); flex-basis:clamp(340px, 28vw, 900px); max-width:46vw;
 margin:clamp(16px, 2vh, 48px); border:1px solid #d6eee226; border-radius:12px;
 background:#131d20; box-shadow:0 20px 80px #00000055;
 padding:clamp(24px, 2.2vw, 72px); gap:clamp(16px, 2vh, 40px);
}
.dq-brand { padding:0 8px 2vh; border-bottom:1px solid #d6eee226; }
.dq-brand-name { color:#b7dccc; letter-spacing:.24em; }
.dq-title { color:#f2f1eb; font-weight:400; }
.dq-menu { gap:8px; }
.dq-menu-btn { border-radius:4px; color:#d3dfda; padding:12px 10px; }
.dq-menu-btn.active { background:#22332e; color:#f2f1eb; border-color:#d6eee226; box-shadow:inset 2px 0 0 #b7dccc; }
.dq-menu-btn:focus, .dq-menu-btn.nav-focused-el { background:#e7eee7; color:#14211d; border-color:#e7eee7; box-shadow:none; }
.dq-menu-ico { background:transparent; color:inherit; }
.dq-menu-label { font-weight:500; }
.modal-layout { width:92vw; height:86vh; border:1px solid #d6eee226; border-radius:12px; background:#141d20 !important; box-shadow:0 24px 80px #00000055; }
.modal-sidebar { background:#0e1619; border-right:1px solid #d6eee226; padding:clamp(24px, 2.5vw, 80px); }
.modal-content-area { padding:clamp(24px, 3vw, 100px); }
.menu-tab { border-radius:4px; color:#b5c4bd; }
.menu-tab.active, .menu-tab:focus { color:#f2f1eb; background:#263c33; }
.filter-btn { border-radius:4px; }
.filter-btn.active, .filter-btn:focus { border-color:#b7dccc; }
@media (max-height:800px) {
 .dq-sidebar { padding:20px; gap:12px; }
 .dq-menu-btn { padding:9px 8px; }
 .dq-menu { gap:4px; }
 .modal-sidebar, .modal-content-area { padding:22px; }
}

button, input, select, textarea { font-family:inherit; }

popups.css:
/* Dialogs share the command panel's edge and quiet accent. */
:scope { font-family:'Segoe UI', system-ui, sans-serif; color:#f2f1eb; }
:scope.edit-modal-overlay { background:#060b0fbb !important; }
:scope.context-menu { background:#172328; border:1px solid #c6e9d83d; border-radius:8px; padding:10px; box-shadow:0 18px 56px #00000066; }
.edit-modal { background:#172328 !important; border:1px solid #c6e9d83d; border-radius:10px; box-shadow:0 24px 80px #00000066; }
.edit-modal-header { border-bottom:1px solid #d6eee226; }
.edit-modal-title { color:#f2f1eb; font-weight:400; }
.modal-btn { border-radius:4px; }
.modal-btn.primary { background:#c6e9d8; color:#14211d; }
.modal-btn:focus-visible { outline:2px solid #f2f1eb; outline-offset:4px; }
.ctx-item:focus, .ctx-item.selected { background:#c6e9d8; color:#14211d; }
.doorpi-update-shell { background:#172328; border:1px solid #c6e9d83d; border-radius:10px; }

/* Editing becomes a right-hand sheet; its fields/actions retain the same DOM. */
:scope.edit-modal-overlay { justify-content:flex-end; align-items:center; padding:4vw; }
.edit-modal { width:clamp(420px, 38vw, 1080px); max-width:92vw; max-height:88vh; }
.edit-modal-header, .edit-modal-body, .edit-modal-actions { padding:clamp(20px, 2vw, 56px); }
.edit-modal-input { border-radius:4px; background:#0e191d; border-color:#d6eee23d; color:#f2f1eb; }
.edit-modal-input:focus { border-color:#b7dccc; box-shadow:0 0 0 1px #b7dccc; }
@media (max-width:1100px) { .edit-modal { width:min(640px, 92vw); } }

button, input, select, textarea { font-family:inherit; }
.edit-modal-input { font-size:clamp(16px, 1vw, 30px); min-height:48px; }
.edit-modal-label { font-size:clamp(12px, .8vw, 24px); color:#b5c4bd; }
.edit-modal-title { font-size:clamp(24px, 1.5vw, 48px); }

login.css:
/* Arrival lounge: asymmetrical heading and square portraits. No new controls or DOM. */
:scope { background:radial-gradient(ellipse at 85% 15%, #29463e 0%, transparent 52%), linear-gradient(115deg, #11191c, #0c1115) !important; color:#f2f1eb; font-family:'Segoe UI', system-ui, sans-serif; }
:scope::before { content:''; position:absolute; inset:0; pointer-events:none; background:linear-gradient(115deg, transparent 52%, #b7dccc0a 52.1%, transparent 72%); }
.doorpi-user-main { align-items:stretch; justify-content:center; }
.doorpi-user-panel .doorpi-panel-head { align-items:flex-start; text-align:left; width:auto; padding-left:0; margin-left:8vw; margin-bottom:clamp(16px, 4vh, 80px); }
.doorpi-panel-title { max-width:15ch; font-size:clamp(30px, 3vw, 88px); font-weight:350; color:#f2f1eb; text-shadow:none; }
.doorpi-panel-sub { color:#b5c4bd; text-align:left; font-size:clamp(14px, 1vw, 30px); }
.doorpi-user-panel .doorpi-avatar { border-radius:14px; background:#233b33; border:1px solid #c6e9d83d; box-shadow:0 18px 40px #00000033; }
.doorpi-user-card:focus .doorpi-avatar, .doorpi-user-card:hover .doorpi-avatar { border-color:#f2f1eb; box-shadow:0 0 0 4px #11191c, 0 0 0 6px #c6e9d8; }
.doorpi-user-card:focus, .doorpi-user-card:hover { transform:translateY(-5px); }
.doorpi-user-card .doorpi-user-name { color:#f2f1eb; font-weight:500; }
.doorpi-user-footer { padding-top:2vh; }
.doorpi-user-clock { color:#b5c4bd; }
.doorpi-power-row { border:1px solid #d6eee226; border-radius:5px; background:#11191c; }
button:focus-visible { outline-color:#c6e9d8; }
@media (max-height:800px) {
 .doorpi-user-panel .doorpi-panel-head { margin-bottom:12px; }
 .doorpi-panel-title { font-size:34px; }
}

button, input, select, textarea { font-family:inherit; }
